mapper.select:
SELECT 
  FROM emp93_sms_notice_target
 WHERE 1=1
   AND emp93_company_id   = #{companyId}
   AND emp93_sms_notice_cd = #{smsNoticeCd}
 ORDER BY emp93_sms_notice_cd, emp93_person_id

SELECT 
  FROM emp93_sms_notice_target
 WHERE emp93_sms_notice_target_id = #{smsNoticeTargetId}
   AND emp93_company_id = #{companyId}

mapper.update:
UPDATE emp93_sms_notice_target
   SET emp93_note = #{note}
 WHERE emp93_sms_notice_target_id = #{id}
   AND emp93_company_id = #{companyId}

mapper.delete:
DELETE FROM emp93_sms_notice_target
 WHERE emp93_company_id = #{companyId}
   AND emp93_sms_notice_target_id IN
#{id}
